P.autoSkillReady=function(d,t){if(d.actions[0]?.op==='knight-kit'){const k=state(this),kind=d.actions[0].kind;if(kind==='sanctuary-judgment'&&d.cell===this.h.cell&&!k.zones.some(z=>z.type==='sanctuary'&&z.life>0))return false;if(kind==='sanctuary-anchor'&&k.zones.some(z=>z.type==='sanctuary'&&z.life>3))return false;if(kind==='war-standard'&&k.zones.some(z=>z.type==='banner'&&z.life>3&&E.dist(this.c,z)<160))return false;if(kind==='crusade-charge'&&k.fervor<3)return false;if(kind==='stored-reprisal'&&(k.barrier>0||(this.c.meters.revenge||0)<this.stats().attack*.5))return false;if(['raised-shield','iron-bulwark'].includes(kind)&&k.guards.some(x=>x.value>= (kind==='iron-bulwark'?.8:.55)&&x.life>.5))return false;if(kind==='sky-aim'&&k.spearCharge>0||kind==='punishment-stance'&&k.counter>1||kind==='blood-awakening'&&k.awaken>1||kind==='half-dragon'&&k.metamorph>1)return false;}return old.auto.call(this,d,t);};
