const distance=k.lastPos?E.dist(c,k.lastPos):0;if(distance<100){if(this.h.cell===3){k.travel+=distance;if(k.travel>=80){k.fervor=Math.min(5,k.fervor+1);k.travel%=80;}}if(k.march>0){k.trailDistance=(k.trailDistance||0)+distance;if(k.trailDistance>=55){k.trailDistance=0;k.trails.push({x:c.x,y:c.y,life:2.4,timer:0,ctx:k.marchCtx});}}}k.lastPos={x:c.x,y:c.y};for(const z of k.trails){z.life-=dt;z.timer-=dt;if(z.timer<=0){z.timer=.6;for(const e of near(this,z,65))if((e.knightFireAt||0)<=this.time&&E.clearLine(z,e,c.zone)){this.damageTechnique(e,.9,z.ctx,'tick');e.knightFireAt=this.time+.6;}}}k.trails=k.trails.filter(z=>z.life>0).slice(-12);
